import{_ as i,c as t,o as l,ag as e}from"./chunks/framework.DfL_BkQ-.js";const g=JSON.parse('{"title":"使い方ガイド","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/usage.md","filePath":"ja/guide/usage.md","lastUpdated":1794112334000}'),r={name:"ja/guide/usage.md"};function o(d,a,n,s,h,c){return l(),t("div",null,[...a[0]||(a[0]=[e('<h1 id="使い方ガイド" tabindex="-1">使い方ガイド <a class="header-anchor" href="#使い方ガイド" aria-label="Permalink to &quot;使い方ガイド&quot;">​</a></h1><h2 id="基本的な操作" tabindex="-1">基本的な操作 <a class="header-anchor" href="#基本的な操作" aria-label="Permalink to &quot;基本的な操作&quot;">​</a></h2><h3 id="画像を開く" tabindex="-1">画像を開く <a class="header-anchor" href="#画像を開く" aria-label="Permalink to &quot;画像を開く&quot;">​</a></h3><ul><li><strong>ファイルメニュー</strong>：ファイル &gt; 開く をクリックして個別の画像を選択します</li><li><strong>フォルダ表示</strong>：ファイル &gt; フォルダを開く をクリックしてディレクトリ全体を閲覧します</li><li><strong>ドラッグ＆ドロップ</strong>：画像ファイルやフォルダをアプリのウィンドウに直接ドラッグします</li><li><strong>Chrome 拡張機能</strong>：任意のウェブサイトで拡張機能のアイコンをクリックすると、すべての画像を表示できます</li></ul><h2 id="finder-同期拡張機能" tabindex="-1">Finder 同期拡張機能 <a class="header-anchor" href="#finder-同期拡張機能" aria-label="Permalink to &quot;Finder 同期拡張機能&quot;">​</a></h2><h3 id="finder-からの素早い画像処理" tabindex="-1">Finder からの素早い画像処理 <a class="header-anchor" href="#finder-からの素早い画像処理" aria-label="Permalink to &quot;Finder からの素早い画像処理&quot;">​</a></h3><p>Finder 同期拡張機能は、画像を素早く処理するための Nicasa ボタンを Finder のツールバーに追加します：</p><ol><li>Finder で 1 つ以上の画像を選択します</li><li>Nicasa のツールバーボタンをクリックします</li><li><strong>画像オプティマイザ</strong> を選ぶとファイルを圧縮、<strong>AI 画像エディター</strong> を選ぶと画像を強化できます</li><li>Nicasa が自動的に起動し、選択したファイルを処理します</li></ol><h3 id="対応形式" tabindex="-1">対応形式 <a class="header-anchor" href="#対応形式" aria-label="Permalink to &quot;対応形式&quot;">​</a></h3><p>この拡張機能は JPG、PNG、GIF、BMP、WebP、SVG、TIFF、ICO ファイルに対応しています。</p><h3 id="サムネイル表示" tabindex="-1">サムネイル表示 <a class="header-anchor" href="#サムネイル表示" aria-label="Permalink to &quot;サムネイル表示&quot;">​</a></h3><p>メイン画面には画像のサムネイルが表示されます：</p><ul><li><strong>クリック</strong>：画像を選択</li><li><strong>ダブルクリック</strong>：全体表示で開く</li><li><strong>右クリック</strong>：オプション付きのコンテキストメニューを表示</li></ul><h3 id="全体表示モード" tabindex="-1">全体表示モード <a class="header-anchor" href="#全体表示モード" aria-label="Permalink to &quot;全体表示モード&quot;">​</a></h3><p>画像を全画面で表示する場合：</p><ul><li><strong>ズーム</strong>：マウスホイールまたはズームコントロールを使用</li><li><strong>パン</strong>：拡大した画像をクリック＆ドラッグして移動</li><li><strong>移動</strong>：矢印キーまたは画面上のボタンで次／前の画像へ</li></ul><h2 id="スクリーンショット機能" tabindex="-1">スクリーンショット機能 <a class="header-anchor" href="#スクリーンショット機能" aria-label="Permalink to &quot;スクリーンショット機能&quot;">​</a></h2><h3 id="スクリーンショットの撮影" tabindex="-1">スクリーンショットの撮影 <a class="header-anchor" href="#スクリーンショットの撮影" aria-label="Permalink to &quot;スクリーンショットの撮影&quot;">​</a></h3><ol><li>ツールバーのスクリーンショットボタンをクリックするか、キーボードショートカットを使用します</li><li>キャプチャしたい領域を選択します</li><li>スクリーンショットが Nicasa で自動的に開き、すぐに編集できます</li></ol><h3 id="画面収録の権限" tabindex="-1">画面収録の権限 <a class="header-anchor" href="#画面収録の権限" aria-label="Permalink to &quot;画面収録の権限&quot;">​</a></h3><p>スクリーンショット機能には画面収録の権限が必要です：</p><ol><li>システム設定 &gt; プライバシーとセキュリティ &gt; 画面収録 に移動します</li><li>Nicasa の横のチェックボックスをオンにします</li><li>必要に応じて Nicasa を再起動します</li></ol><h2 id="ai-画像エディター" tabindex="-1">AI 画像エディター <a class="header-anchor" href="#ai-画像エディター" aria-label="Permalink to &quot;AI 画像エディター&quot;">​</a></h2><h3 id="ai-エディターの概要" tabindex="-1">AI エディターの概要 <a class="header-anchor" href="#ai-エディターの概要" aria-label="Permalink to &quot;AI エディターの概要&quot;">​</a></h3><p>Nicasa には強力な AI 画像強化ツールが組み込まれています：</p><ul><li><strong>自動補正</strong>：画質を自動的に向上</li><li><strong>スマート切り抜き</strong>：インテリジェントな切り抜き提案</li><li><strong>色補正</strong>：AI による色調整</li><li><strong>ノイズ除去</strong>：ノイズや粒状感を除去</li><li><strong>シャープ化</strong>：アーティファクトを生じないインテリジェントなシャープ化</li></ul><h3 id="インペイントツール" tabindex="-1">インペイントツール <a class="header-anchor" href="#インペイントツール" aria-label="Permalink to &quot;インペイントツール&quot;">​</a></h3><p>インペイントツールでは次のことができます：</p><ul><li>画像から不要なオブジェクトを削除</li><li>欠損部分をインテリジェントに補完</li><li>損傷した領域を修復</li><li>背景をクリーンアップ</li></ul><h2 id="透明オーバーレイモード" tabindex="-1">透明オーバーレイモード <a class="header-anchor" href="#透明オーバーレイモード" aria-label="Permalink to &quot;透明オーバーレイモード&quot;">​</a></h2><p>デザイナーやアーティストに最適です：</p><ol><li>Nicasa で画像を開きます</li><li>「表示」メニューからオーバーレイモードを有効にします</li><li>スライダーで透明度を調整します</li><li>画像は他のすべてのウィンドウの前面に表示され続けます</li><li>トレース、参照資料との照合、UI 比較にご利用ください</li></ol><h2 id="キーボードショートカット" tabindex="-1">キーボードショートカット <a class="header-anchor" href="#キーボードショートカット" aria-label="Permalink to &quot;キーボードショートカット&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ショートカット</th><th>動作</th></tr></thead><tbody><tr><td><code>Cmd+O</code></td><td>ファイルを開く</td></tr><tr><td><code>Cmd+Shift+O</code></td><td>フォルダを開く</td></tr><tr><td><code>Space</code></td><td>次の画像</td></tr><tr><td><code>Shift+Space</code></td><td>前の画像</td></tr><tr><td><code>Cmd+F</code></td><td>フルスクリーンの切り替え</td></tr><tr><td><code>Cmd+W</code></td><td>ウィンドウを閉じる</td></tr><tr><td><code>Cmd+Q</code></td><td>アプリを終了</td></tr><tr><td><code>Delete</code></td><td>現在の画像を削除</td></tr><tr><td><code>Cmd+S</code></td><td>スクリーンショットを撮る</td></tr><tr><td><code>Cmd+E</code></td><td>AI エディターを開く</td></tr><tr><td><code>Cmd+T</code></td><td>オーバーレイモードの切り替え</td></tr></tbody></table><h2 id="chrome-拡張機能との連携" tabindex="-1">Chrome 拡張機能との連携 <a class="header-anchor" href="#chrome-拡張機能との連携" aria-label="Permalink to &quot;Chrome 拡張機能との連携&quot;">​</a></h2><h3 id="インストール" tabindex="-1">インストール <a class="header-anchor" href="#インストール" aria-label="Permalink to &quot;インストール&quot;">​</a></h3><ol><li><a href="https://chromewebstore.google.com/detail/nicasa-image-viewer/cihceekeiedkinpjjjfehlgjdhpeokbj" target="_blank" rel="noreferrer">Nicasa Chrome 拡張機能</a>をインストールします</li><li>ブラウザのツールバーに拡張機能のアイコンが表示されます</li></ol><h3 id="使い方" tabindex="-1">使い方 <a class="header-anchor" href="#使い方" aria-label="Permalink to &quot;使い方&quot;">​</a></h3><ol><li>任意のウェブサイトにアクセスします</li><li>Nicasa 拡張機能のアイコンをクリックします</li><li>ページ上のすべての画像がグリッドで表示されます</li><li>任意の画像をクリックすると Nicasa で開きます</li><li>ウェブ画像に対して Nicasa のすべての機能を利用できます</li></ol><h2 id="設定" tabindex="-1">設定 <a class="header-anchor" href="#設定" aria-label="Permalink to &quot;設定&quot;">​</a></h2><p>Nicasa &gt; 環境設定 から設定にアクセスできます：</p><ul><li><strong>一般</strong>：既定のフォルダ、言語、テーマ</li><li><strong>表示</strong>：サムネイルのサイズ、ズームの動作、アニメーション</li><li><strong>エディター</strong>：AI ツールの設定、既定の補正項目</li><li><strong>拡張機能</strong>：Chrome 拡張機能の設定</li><li><strong>プライバシー</strong>：データ収集の設定</li></ul><h2 id="対応形式-1" tabindex="-1">対応形式 <a class="header-anchor" href="#対応形式-1" aria-label="Permalink to &quot;対応形式&quot;">​</a></h2><p>Nicasa は一般的な画像形式すべてに対応しています：</p><ul><li><p><strong>標準</strong>：JPEG、PNG、GIF、BMP、TIFF、WebP</p></li><li><p><strong>RAW</strong>：CR2、NEF、ARW、DNG（変換を伴います）</p></li><li><p><strong>ベクター</strong>：SVG（ラスタライズを伴います）</p></li><li><p><strong>アニメーション</strong>：GIF、APNG</p></li><li><p>JPEG/JPG</p></li><li><p>PNG</p></li><li><p>GIF（静止画）</p></li><li><p>BMP</p></li><li><p>TIFF</p></li><li><p>WebP</p></li><li><p>HEIC（対応システム上）</p></li></ul><h2 id="ヒントとコツ" tabindex="-1">ヒントとコツ <a class="header-anchor" href="#ヒントとコツ" aria-label="Permalink to &quot;ヒントとコツ&quot;">​</a></h2><ul><li>検索バーを使ってファイル名で素早く画像を探せます</li><li>フォルダで画像を整理してコレクションを作れます</li><li>評価システムでお気に入りの画像に印を付けられます</li><li>「ファイル」メニューから別の形式で画像を書き出せます</li></ul>',47)])])}const p=i(r,[["render",o]]);export{g as __pageData,p as default};
